UPDATE questions SET disabled=1 WHERE id=297666 AND answer='A' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297667 AND answer='A' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297671 AND answer='B' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297672 AND answer='A' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297673 AND answer='A' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297674 AND answer='ABCD' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297675 AND answer='ABCD' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297676 AND answer='B' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297679 AND answer='B' AND disabled=0;
UPDATE questions SET explanation='“聆听”更贴合细听自然之声的语境，“倾听”多用于听取意见或说话。第二空“守望”兼有守着与遥望之意，与“见证着山河沧桑”的时空感相呼应；“守护”则偏重实际保护。第三空“沉淀”可指历史、记忆的积聚，“沉潜”指潜伏或潜心，不能带“历史岁月”作宾语。故C项最恰当。' WHERE id=297684 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='这句话出自魏征《谏太宗十思疏》，原文为“求木之长者，必固其根本；欲流之远者，必浚其泉源；思国之安者，必积其德义”。“固”意为稳固根基，“浚”指疏通泉源，“积”指积累德义，三者分别对应树木、水流、治国，语义精准。干扰项多因混淆“固”与“积”的搭配对象，或误将“浚”用于树木，故排除。' WHERE id=297687 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一空“耳根清净”为固定搭配，指没有嘈杂声干扰，排除A、C的“静”。第二空“战斗历程”指过程，而“里程”多用于道路或比喻性进程，此处“历程”更准确。第三空“申明”侧重郑重说明，符合“为了避免误会”的语境；“声明”多指公开表态。第四空“推脱”指推卸责任，与“埋怨”并列恰当；“推托”借故拒绝，不符。故选B。' WHERE id=297688 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297690 AND answer='A' AND disabled=0;
UPDATE questions SET explanation='D项“避免造成社会误解”中，“误解”可指社会对命名规范的误解，也可指社会对中成药本身的误解，歧义在于误解对象不明确。A、B、C项语义清晰，无歧义。故选D。' WHERE id=297691 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干诗句表达的是忧国忧民、心系天下的深沉情感。A项“奋不顾身以殉国家”是舍身报国，C项“苟利国家生死以”是生死以之的爱国担当，D项“位卑未敢忘忧国”直接体现忧国情怀，三者均与题干一致。B项描绘卢沟桥畔折柳送别的离愁别绪，侧重个人离别之情，与家国忧思无关，故为不一致项。' WHERE id=297693 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='横线处位于段首，需总领后文。后文强调画家“抒发胸中逸气”、作品“倾注思想精神”，并以“有感而发”为关键，落脚于“自我心灵与山水灵性的结合”，核心是情感表达。A项“重视意象”虽提及，但后文更侧重情感基础，且“意象”只是手段；B项“意象是生命”过于绝对，偏离情感主线；C项“不单纯描写自然”仅否定表象，未点出情感内核。D项直接呼应“移情言志”与“心灵结合”，最贴合文意。' WHERE id=297695 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段先指出限制城市资本下乡，因为土地是农民的最后退路与基本保障，且基本保障不应交易，否则农民进城失败后可能无路可走。可见作者认为当前城乡二元体制虽限制资本下乡，但客观上保护了农民的基本生存保障，因此选C。A、B与文意相反，文中已清除或正在清除限制农民进城的障碍；D项“影响一体化进程”文中未提及，且作者更强调保护意义而非负面影响。' WHERE id=297696 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段列举日本两地气温上升与苹果酸甜变化、新疆与南京红提颜色甜味差异、法国葡萄酒因雨热条件不同口味不同，均指向气温（光热）条件对水果甜度、色泽的影响。A项过度引申为“全球变暖”且未提色泽；C、D项只涉及“不同地方”而忽略核心“气温上升”及甜度变化，均不全面。' WHERE id=297697 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='A项“之”是代词，指代对方/敌军，作“使”的宾语；B“吾之所长”、C“长短之术”、D“人之情”中的“之”均为结构助词，相当于“的”或用于修饰限制关系。故用法不同的是A项。' WHERE id=297701 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297703 AND answer='B' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297704 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='研究显示，学习记忆会使突触的形态、数量和连接方式发生改变，比如恐惧训练后侧杏仁核—听觉皮层突触明显增多。A项却说这些方面都不会随学习记忆改变，与研究发现相悖。B、C、D均能对应研究成果，故本题错误表述为A。' WHERE id=297705 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297706 AND answer='A' AND disabled=0;
UPDATE questions SET explanation='列车转弯时做圆周运动，需要指向圆心的向心力。若内外轨等高，车轮轮缘与钢轨接触，向心力只能由外轨对车轮的水平弹力提供，因此外轨承受侧向挤压，磨损更严重。内轨不提供向心力，磨损较轻。重力竖直向下，不指向圆心，不能作为向心力，故C、D错误。B将磨损对象说反，排除。' WHERE id=297708 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='拍完合照后改拍单人照，需要让人物在画面中占比变大，所以相机应靠近被摄者。同时，单反相机对焦距离变近时，镜头需要前伸（向外伸出）才能合焦，因此正确操作是“离人近一些，镜头前伸”。若镜头后缩则无法对近处物体清晰成像，离远则人物变小，均不符合要求。' WHERE id=297709 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干逻辑链：严格自律→底线思维→不忘初心→坚守理想信念。B项“只有不忘初心，才能做到严格自律”即严格自律→不忘初心，与题干链条一致。A项将“不能严格自律”与“丧失底线思维”混同，属于否前错误；C、D项均将“坚守理想信念”或“不忘初心”作为充分条件，而题干中它们只是必要条件，方向反了。' WHERE id=297712 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干由捕捞量大幅减少推出价格回升，隐含前提是供应减少能直接影响市场，即需求端没有其他替代来源。若人工养殖已解决，供应缺口可被填补，价格未必回升；反之，养殖难题未解则捕捞量减少必然导致供应紧张，价格上升。A、B、C均与价格形成机制无关，无法支撑因果链条。' WHERE id=297713 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干观点是：互联网金融导致银行低成本资金搬家，是传统银行业面临挑战的重要原因。要支持此观点，需说明人们闲置资金确实只能选择银行或互联网金融，从而资金搬家必然发生。C项指出除两者外无其他去向，排除了资金流向其他渠道的可能，强化了“搬家”与互联网金融的因果联系。A项强调风险，反而削弱；B项仅说明过去资金在银行，未涉及搬家原因；D项服务水平优于互金，与资金搬家无关。故C项最能支持。' WHERE id=297714 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干论点是苔藓类地被植物导致地球氧气大增。C项直接揭示了苔藓蔓延通过增加有机碳含量进而提升氧气含量的具体机制，建立了因果联系，支持力度最强。A项虽提到陆生植物提升氧气，但未明确指向苔藓，且“最早出现的陆生植物”与苔藓类地被植物不完全等同。B项仅估算苔藓产氧占比，未说明氧气大增的因果关系。D项是氧气增加的结果，属于因果倒置，不能支持。' WHERE id=297716 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干指出传统经验式表述“很难融入现当代语境”，即难以在现当代语境中有效传播，A项直接推出。B项“无法解读”过于绝对，题干仅说“近于隔靴搔痒”，并非完全无效。C项混淆了“借助西方美学解读传统书法”与“以传统心态解读西方文明”的类比关系，并非等同。D项“其他领域没有类似尴尬”无中生有，题干只谈书法，未比较其他领域。' WHERE id=297717 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干说每块绿地都配垃圾桶，且垃圾桶必标“可回收”或“不可回收”。Ⅰ不一定真，因为可能所有垃圾桶都标“不可回收”，没有“可回收”的。Ⅱ正确：若一块绿地没配垃圾桶，它就不可能是公共场所，因为公共场所的绿地都配了，逆否命题成立。Ⅲ错误：题干只说公共场所的绿地配垃圾桶，没说配了垃圾桶的绿地一定属于公共场所，可能其他场所也配。所以只有Ⅱ一定真。' WHERE id=297718 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='由条件Ⅴ，迎新春宣传和微信维护都由副主席负责；条件Ⅳ说只有负责这两项之一，王主席才在本市过年，而王主席是主席不负责这些工作，故王主席只能在外地过年，且不参与这两项寒假工作，A项为真。由条件Ⅲ只能推出李或张至少一人在本市，但无法确定具体是谁，B、C、D均不必然成立。' WHERE id=297720 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297721 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='题干由酒驾事故数量是疲劳驾驶的2倍，推出禁止疲劳驾驶宣传做得更好，隐含假设是事故数量与宣传效果直接相关。A项直接询问两者是否有直接关系，若无关则结论不成立，若有关则支持结论，能评价论证。B项只涉及未来趋势，不评价当前宣传效果；C项讨论疲劳驾驶是否必然出事故，偏离宣传比较；D项关注加大酒驾宣传的降幅，未涉及疲劳驾驶宣传，无法对比。考点为论证评价中的隐含假设。' WHERE id=297722 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干条件：大多数中年乘客买意外险，金卡及以上会员都买延误险，意外险和延误险互斥。由“大多数中年乘客买意外险”可知至少有一个中年乘客买意外险，而买意外险者不买延误险，所以Ⅰ“有中年乘客没买延误险”必真。金卡会员都买延误险，而买延误险者不买意外险，所以Ⅱ“金卡会员都没买意外险”必真。Ⅲ说“有中年乘客买延误险”，但题干只保证大多数买意外险，剩余少数中年乘客可能买延误险也可能不买，无法推出。故正确项为D。' WHERE id=297723 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297725 AND answer='B' AND disabled=0;
UPDATE questions SET explanation='第①句说把期盼放到侠客身上，“寄于……身上”搭配恰当；第②句“寄予厚望”是固定搭配；第③句侧重生活每天给我们什么，“给予”表一般性给予，“赋予”偏重使命、权利、意义等庄重事物。故选B。' WHERE id=297728 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='首句应引出蝉在夜晚活动的场景，⑤以“夜幕降临”开篇，适合作为总起。①具体描述幼虫羽化过程，紧承⑤的“忙碌起来”。④说明蝉选择夜晚蜕变的原因，与①的“黄昏及夜间”衔接自然。③强调蜕变受干扰的后果，解释④中“避免干扰”的必要性。②以“因此”总结，收束全段，点明夜晚是蝉活动高峰。A项以①开头突兀，且②无法承接④；C项④开头缺乏铺垫；D项③开头偏离叙述主线。故选B。' WHERE id=297729 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='C项“八十挂零的耄耋老翁”语义重复，“耄耋”指八十至九十岁，与“八十挂零”赘余，且“老翁”多余。A项表述清晰，B项“面积166万平方公里”与“最大的省级行政区”搭配合理，D项比喻生动无语法错误。故答案为C。' WHERE id=297730 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='B、C、D都在强调实践、实验对获取知识、检验真理的重要作用；A则强调从不同角度看世界，侧重视角的多样性，并非强调实践。因此含义与其他几项不一致的是A。' WHERE id=297731 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='乾隆帝针对奏章中“书生不能胜任”等说法展开驳斥，先肯定读书对修己治人的意义，再强调真正能当“书生”之称者应行宽和之政，最后点明那些以“书生”相诟病的人，恰是因不读书而迂谬疏庸，并非书生之过。全篇核心在于批判“以书生相诟病”者的无知，而非泛论读书意义或不读书危害，也非单纯希望官员爱民。故C项最贴合旨意。' WHERE id=297733 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段以智珠寺修复为例，强调文物不仅是房子，更是历史信息的载体，包括曾受的破坏和灾难，因此修复时不应涂得面目一新。核心是“本着这样的原则”去认识文化遗产，即要真实保留其原貌，而非仅强调承载信息或具体痕迹。A项是论据而非目的，C项过于片面，B项非意图所在。故选D。' WHERE id=297734 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段先述中西部抢人才现象，再析人才对城市转型的关键作用，结尾“因此”应总结人才的核心驱动价值。B项“人才是城市未来发展的引擎”承接前文并呼应后文，最贴切。A项“重塑经济版图”过度引申；C项偏向对策，不符分析性总结；D项比较人力资本与物质资源，文中未提及。故选B。' WHERE id=297735 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段首句抛出“教育的焦虑为何愈演愈烈”的疑问，随后指出培训机构利用家长心理，将“洗脑”阵地前移到手机，并通过微信群散播紧张信息、制造焦虑，最后以商业中心变身“超级学校”佐证。可见核心是培训机构在助推家长焦虑，而非单纯描述焦虑现象或家长被迫参加培训。A项过于宽泛，B项只是设问未点明原因，C项偏离“焦虑”主题。故选D。' WHERE id=297736 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段明确说核聚变技术“仍是一个遥远的梦想”，但并未说核技术是“人类的终极梦想”，且核裂变技术昂贵且饱受争议，显然不是终极梦想，D项过度引申且与文意不符。A项可由“可再生能源……风能、太阳能”推出；B项由“为了抵抗气候变化……解决碳排放”可合理推断；C项由“放弃肮脏的化石燃料”可知化石燃料不清洁。故D项不符合文意。' WHERE id=297737 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='这句话先以“也许有人会说”主动让步，承认对方“捐了真金白银”的合理性，再通过“问题在于”转折，引出对“以广告为目的的慈善”的批评，并进一步用“事实证明”强化反驳。它并非单纯反驳或递进，而是先立后破，为后文解释和反驳提供靶子，因此选C。A项“造成转折”不全面，B项“全新问题”不准确，D项“强化前文”与让步逻辑不符。' WHERE id=297738 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='秘鲁水源条件居中，霍乱既可通过水源传播，也需依赖人际接触，病菌须在宿主体内增强毒性以维持传播，进化压力最大。厄瓜多尔水源最差，病菌主要经水源扩散，无需适应宿主，毒性进化弱；智利水源虽好，但病例少、传播链短，压力有限。故选B。' WHERE id=297739 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297740 AND answer='D' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297741 AND answer='A' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297742 AND answer='A' AND disabled=0;
UPDATE questions SET explanation='活板印刷是北宋毕昇发明的，唐代尚未出现，A错在时代。其底板为铁板而非铁制模具，字印用胶泥刻制而非木刻，B错。字印按韵（音序）收纳于木格，但平常不用时是“以纸贴之”，并非贴上纸后按音序收纳，C表述不准确。D正确，铁板与字印间敷松脂、蜡、纸灰混合物，加热熔化可控制黏合与脱落，符合《梦溪笔谈》记载。' WHERE id=297743 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297744 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='文段重点围绕活板印刷的操作流程展开，详细描述了制字、排版、印刷等步骤，并解释了其“极为神速”的原因在于字模可重复使用、排版灵活。A项仅提及地位，非主题；B项是影响，非主要内容；C项虽涉及工艺差异，但文段侧重操作与效率，而非差异本身。故D项最贴合文意。' WHERE id=297745 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='半潜船装货需先下潜：开启通海阀门注水使船体下沉，再将货物移至甲板，随后用空压机注入空气排水，船体上浮，最后运走。②在①前，排除A、D；④在③后，排除C。正确顺序为②①③④⑤，故选B。' WHERE id=297749 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干关键句为必要条件假言命题：沉着应对→增强忧患意识，其逆否命题即“不增强忧患意识→无法沉着应对”，与D项一致。A项误将“应对挑战”当充分条件，且题干未涉及其与实现梦想的必然联系；B项夸大题干“并不比……少/容易”为“多很多/难很多”；C项“风平浪静”属无中生有。故D项正确。' WHERE id=297751 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干由木星卫星多由水冰构成，推出木星大气层含水。D项指出卫星与行星由相同物质形成，说明卫星上的水冰来源与木星一致，从而支持木星大气层应有水。A项卫星跌落需极长时间且未直接关联大气水；B项气态水存在与木星是否含水无关；C项天王星类比力度弱，且未涉及卫星与行星关系。故D项最能支持。' WHERE id=297754 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='C项指出被研究者中超半数已大学毕业，而题干中基因得分最低者仅约5%能毕业、最高者约50%能毕业，说明整体毕业率可能已接近或高于50%，基因得分与毕业率的差异或仅反映样本中高学历者偏多，而非基因决定学历，直接削弱“极大联系”。A项“不到50%”与题干数据不冲突；B项父母学历无关；D项中间者也能毕业，反而支持关联。' WHERE id=297755 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='除非P，否则Q等价于¬P→Q；题干Q是“不能申请”，所以“能申请”可推出“业主家出现飞蛾”。老王家的飞蛾只能推出A小区有的业主家有飞蛾，推不出有业主家没有飞蛾，也推不出A小区可以申请；B小区能申请只能推出B小区至少一户业主家有飞蛾，推不出所有业主家都有飞蛾。因此三项都不能断定真假。' WHERE id=297756 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干结论是蚂蚁可能成为新型抗生素来源，前提需说明蚂蚁产生的抗菌素能有效对抗病原体且病原体未对其产生抗药性。A项直接指出侵袭蚂蚁的病原体未对蚂蚁抗菌素形成抗药性，排除了抗药性风险，使结论成立。B项只说明蚂蚁有抗菌机制，未涉及抗药性；C项杀菌效力差异与能否作为新型抗生素无关；D项讲真菌劫持蚂蚁，反而削弱蚂蚁抗菌能力。故A是必要前提。' WHERE id=297757 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干由“新进厂技术工人学历层次提高”推出“整体素质提升”，需建立学历与素质的关联。A项说明新工人仍在岗，使样本有效；C项直接建立学历与素质的正相关；D项说明学历高者能带动他人，均能支持。B项仅说明高素质工人产品合格率高，与学历提升导致素质提升的推理无关，无法支持结论。故选B。' WHERE id=297758 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干由爱因斯坦通过相对论计算得出宇宙质量为零，且若反物质不存在则计算不会得出此结果，推出反物质仍存在。论证依赖计算结果的可靠性，若计算本身有误，则后续推理失去基础。因此必须假设爱因斯坦的计算是正确的。A项“只存在一个宇宙”与反物质存在与否无关；C项涉及星际探索，偏离主题；D项实验室发现或制造反物质，不能直接支持宇宙中反物质的存在，且非必要前提。故正确项为B。' WHERE id=297759 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干结论是二氧化碳负面作用居多，但前文只提到它有正反两面，并未说明哪面更强。D项直接指出温室效应抵消并超过固碳效应，用观测数据补上了“负面更强”的关键证据，使结论成立。A项比较重要性，反而可能支持正面；B项只强调对植物的好处，属正面；C项说关键在人类利用，偏离了二氧化碳自身作用的比较。考点是补充论据解释结论。' WHERE id=297760 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='将(1)理解为中标者为甲或乙。若中标者是甲或乙，则(1)(2)(3)都真，与“只有一人正确”矛盾；若中标者是丁，则(2)(3)都真，也矛盾。故中标者只能是丙、戊、己之一。无论三者中哪一个中标，甲、乙、丁都未中标，所以C项可确定。A、B、D均含有可能中标的高校，不能确定为三所均未中标。' WHERE id=297761 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='甲第4，且乙、丙、丁都在甲之前、丁在乙前，故前3名只能是丁丙乙或丁乙丙等组合。结合“己和丙之间隔两人”：若丙第2则己第5；若丙第3则己第6。若己第6，则己为外国选手，且戊只能在第5或第7，都会与“外国选手前一名为中国选手”矛盾。故己第5、丙第2、乙第3。第6名为外国选手且戊为外国选手，只能戊第6，庚第7，所以乙和庚之间隔3人。' WHERE id=297762 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297776 AND answer='D' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297778 AND answer='B' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297786 AND answer='A' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297787 AND answer='A' AND disabled=0;
UPDATE questions SET explanation='习近平在首届进博会主旨演讲中宣布了多项开放举措，其中明确提到“增设中国上海自由贸易试验区的新片区”，这是直接针对上海开放定位的决策。B项科创板虽也在上海，但属于资本市场改革，并非演讲中“发挥上海开放作用”的直接表述；C项是上海自身发展策略，非国家层面开放决定；D项长三角一体化虽上升为国家战略，但并非该演讲中针对上海开放的具体宣布内容。考点在于区分演讲中明确提出的开放措施与上海其他发展政策。' WHERE id=297788 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297794 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='该项改革以流程再造、标准化法治化为基础，以“互联网+政务服务”为支撑，本质是政府自我革命，最终形成公众、企业、政府共赢。B错在“增强部门利益”：改革要理顺职责、强化责任，不是强化部门利益。' WHERE id=297797 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一空，“懵懵懂懂”形容年少时对世事认识不清，更贴合“青年时代”的语境；“稀里糊涂”侧重行为糊涂，不如前者贴切。第二空，“蜕变”指身份、状态的质变，从学生到职业人正是这种转变；“改变”过于宽泛。第三空，“顺顺当当”强调过程顺利，与“不是……的”呼应，而“风平浪静”多指局势平静，不适用于个人成长。故D项最恰当。' WHERE id=297799 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='“水力”指水流产生的动力，用于发电站建设；“水利”指水利工程或农田灌溉，与发电站不直接搭配。后文“工程一直不前”需搭配“停滞”，表示因资金问题而暂停进展；“停止”强调完全终止，与“一直”和“不前”的持续状态不符。故选C。' WHERE id=297801 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='“一言以蔽之”意为用一句话概括，通常用于总结归纳。A项中“被王熙凤一言以蔽之”搭配不当，该成语不能用于“被”字句，且此处语境是“被蒙蔽”，与“概括”无关。B、C、D项均正确使用“概括”义，分别用于总结原因、说明难以概括、引出总括性观点。故选A。' WHERE id=297804 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='先提出储存鸡蛋的正确方法（③），再解释原因（②），接着补充细节（①），最后总结好处（④）。③为首句，②承接“为什么”，①具体说明蛋清变稀后的物理原理，④收尾。排除A、B，D将④提前，逻辑断裂，故选C。' WHERE id=297805 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段先讲校园贷危害及治理，但重点在后半句“大学生也有教训可以吸取”，指出其自身过度消费、认识不足的问题。因此结论应落在大学生自身反思与自律上，而非继续强调外部治理或单纯远离、认识危害。B项“有必要进行反思加强自律”既承接前文教训，又涵盖认识与行为层面，最全面。A项偏离“因此”前的大学生主体；C、D项虽相关，但仅针对单一层面，不如B项综合深刻。' WHERE id=297808 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干问“不是”范仲淹采取的救荒措施。范仲淹在杭州救灾时，鼓励赛舟、修寺庙、建仓库等以工代赈，这些均见于记载。而“打开自家谷仓赈济灾民”是其他官员或乡绅的常见做法，并非范仲淹此次救荒的典型措施，故A为正确项。B、C、D均为其主动引导的公共工程或活动，属于干扰项。' WHERE id=297812 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='过氧化氢受热易分解，浓缩时需降低沸点以避免高温分解。减压蒸馏通过降低体系压力使液体沸点下降，可在较低温度下蒸发水分，实现浓缩。常压蒸馏需加热至较高温度，会加速过氧化氢分解；加压蒸馏沸点更高，更不利；生石灰遇水放热且与过氧化氢可能发生反应，均不适宜。' WHERE id=297814 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干前提：真正关心老百姓利益→受尊敬，且→重视民生。结论：不重视民生→不受尊敬。要推出此逆否形式，需补充“受尊敬→真正关心老百姓利益”，即D项。A、C与推理无关；B项“重视民生→受尊敬”方向相反，无法串联。考点为三段论补前提，需找结论与前提间的缺失链条。' WHERE id=297816 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干关键句是“只有尊重自然规律，才能有效防止在开发利用自然上走弯路”，这是必要条件假言命题，可翻译为“防止走弯路→尊重自然规律”。其逆否命题是“不尊重自然规律→不能防止走弯路”，即A项。B项将必要条件误作充分条件，错误；C项和D项均与题干逻辑无关，不能必然推出。' WHERE id=297817 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='张教授由“大多数教师叫不出委员姓名”推出“委员会工作最没有影响力”，隐含的假设是教师对委员的熟悉程度能反映委员会工作的影响力。C项直接建立了这一联系，是必要前提。A项“不感兴趣”与影响力无关；B项“只有委员才有资格评价”过于绝对，且题干未涉及评价资格；D项讨论遴选时的知名度，与当前工作影响力无直接关联。考点为论证中的隐含前提，需在论据与结论间搭桥。' WHERE id=297818 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干以火灾数据下降为依据，宣称政府投入有效。削弱需说明数据下降另有原因。B项指出去年出现异常持续降雨，降雨会直接降低火灾发生和蔓延，属于典型的“另有他因”削弱，最能动摇结论。A项说投入低于往年，但题干强调“支出数百万美元”，且低于往年不等于无效，削弱力度弱。C项邻国火灾未减少与本国无关。D项费用占比小不能说明效果差，均非直接因果削弱。' WHERE id=297819 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297820 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='总经理意见是：欧洲线和北美线至少开通一条（即欧或北至少一），且南美线不能马上开通。董事长反对，即否定整个联言命题，等价于：要么南美线马上开通，要么欧洲线和北美线都不开通。选项D表述为“如果南美线不能马上开通，那么欧洲线和北美线都不能开通”，正是对原命题的否定（¬P或Q，其中P为南美线马上开通，Q为欧北都不开通），逻辑等价。A、B、C均未准确表达否定联言命题的完整含义，故D正确。' WHERE id=297821 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干条件：23岁以上且身高超1.83米→参加阅兵。因此未参加者必不同时满足两条件，D项正确。A项“无23岁以下参加”超出题干限定，无法推出；B项“占多数”无人数依据；C项“超1.83米但23岁以下”不在条件范围，均排除。考点为充分条件且关系否定。' WHERE id=297822 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='甲“所有同学都及格”与丙“并非所有同学都及格”是矛盾关系，二者必然一真一假。题干说只有一人猜错，因此乙、丁都猜对。乙真说明小张没有及格；由此可推出并非所有同学都及格，所以丙真、甲假。故选B。' WHERE id=297823 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='由(4)知珍稀品种都是玫瑰，又由(1)玫瑰都种植在东区，所以珍稀品种必然都在东区。西区是牡丹园，种植的是牡丹，不可能有玫瑰，更不可能有珍稀品种，故“西区牡丹中有珍稀品种”必然为假。B、C、D均无法由题干必然推出或否定，不是必然为假。' WHERE id=297824 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='假定去挪威：父亲要求不去丹麦和冰岛，于是不去冰岛；母亲又要求去挪威和丹麦，前后矛盾，故不去挪威。儿子的话前件成立，推出瑞典和芬兰；母亲的话后件因不去挪威而为假，要使其成立，“不去冰岛”必须为假，所以去冰岛。因此可得出“去瑞典、芬兰和冰岛”，答案B。' WHERE id=297825 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='“甲或乙之一”应理解为甲、乙中恰有一人。若甲、乙均任正科级，则正科为甲、乙，副科为丙、丁；（1）（2）的前件均因并非“之一”而不成立，（3）前件丁正科也不成立，故该情况可能。B、C都会使（1）前件成立而推出丁正科，与正科人数/已有组合矛盾；D会使（3）推出丙正科，与丙副科矛盾。' WHERE id=297826 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='设专科毕业男为a，专科毕业女为b，非专科毕业男为c，非专科毕业女为d。条件为a+b>c+d且b+d>a+c。两式相加得2b>2d，即b>d，即专科女多于非专科女。又由b>d及b+d>a+c，可推出b>c，即专科女多于非专科男，故（3）真。（1）和（2）无法必然推出，排除。' WHERE id=297827 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干通过港珠澳大桥设计成S型曲线，说明工程师在认识水流冲击和海底地形规律的基础上，主动调整设计以顺应规律、减少危害。这体现了人能发挥主观能动性去认识事物的本质和规律，并据此行动。B项中“改变规律起作用的具体方式”表述不准确，规律本身不可改变，只能改变利用方式；C、D项夸大了意识作用，意识不能直接创造客观事物或直接变观念为现实。' WHERE id=297833 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='1964年三届全国人大一次会议上，周恩来在政府工作报告中正式提出“四个现代化”为现代农业、现代工业、现代国防和现代科学技术。选项B“现代国防”与“现代科学技术”并列，构成完整表述；A、C虽属现代化范畴，但非当时官方表述中的固定搭配，故排除。' WHERE id=297905 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='“三步走”战略目标是邓小平在1987年提出的，第一步是解决人民温饱问题，第二步是到20世纪末人民生活达到小康水平，第三步是到21世纪中叶基本实现现代化。题干问的是“改革开放之后”提出的“三步走”战略目标，且选项为单一步骤，A项是第一步目标，符合题意。B项是第二步，C项是新时代目标，D项是第三步，均非题干所指的“第一步”。' WHERE id=297906 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297907 AND answer='A' AND disabled=0;
UPDATE questions SET explanation='全面实施绩效管理强调对预算、政策、项目等各环节进行整体统筹与协同推进，避免碎片化管理，因此整体性原则是核心要求。公益性原则属于公共管理的价值取向，并非绩效管理的实施原则；科学性和公开性虽与绩效管理相关，但题干问的是“全面实施”所体现的总体原则，整体性更贴合“全面”的语义，故排除B、C、D。' WHERE id=297909 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一空“文明”与“野蛮”是相对而生的概念，用“相对应”更契合定义性语境；“对立”虽也可表相反，但不如“对应”自然。第二空“紧密相连”为常见搭配，表示文明进程与处理自然关系密不可分。第三空后文强调按自然规律、取用有度，人与自然是“互动”关系，而非“斗争”“妥协”或“了解”。' WHERE id=297928 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一句写云雾随风变化，强调动态的“变”，用“千变万化”最贴切；第二句写雪花飘落时的各种姿态，用“千姿百态”形容形态多样；第三句写石笋形状怪异，用“千奇百怪”突出奇特。B、C、D均将词语与语境错配，故选A。' WHERE id=297929 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一空用“也许”表示不确定的回忆，符合多年后追忆的口吻；第二空“可是”转折，强调即便身处他乡，回忆依然清晰；第三空“还是”呼应转折，突出记忆的顽固。A项“尽管/甚至/总是”中“甚至”表递进，与“回忆”逻辑不符；B项“哪怕/只要/就”构成条件假设，但“哪怕”后应接极端情况，且“只要…就”过于绝对；D项“虽然/但是/仍然”转折过强，且“虽然…但是”搭配后“仍然”略显冗余，不如“可是…还是”自然。' WHERE id=297930 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一空，“确”表肯定，承接前文“不免物换星移”，强调文化变化确实存在，而“却”表转折，与语境不符。第二空，“延续”指持续不断，符合“这种情况”从宋代以后一直存在的语义；“沿续”是生造词。第三空，“隔绝”强调完全断开，与后文“并非完全”及士大夫与民间文化相互影响的例子呼应；“隔离”“剥离”“分隔”均侧重具体分开，不如“隔绝”贴切。故选C。' WHERE id=297931 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='第一空，“灭绝”带给人的是心理上的沉重感，“凝重”侧重庄重严肃，多形容气氛或神情，不贴合语境。第二空，长江白鲟最后一条独自存活，用“孤独”强调无伴，“孤苦”偏重生活困苦，文中未体现。第三空，“希望渺茫”是固定搭配，指可能性极小，而“迷茫”指困惑，与希望搭配不当。故选B。' WHERE id=297932 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='“时速”本身含“每小时”之意，与“600多公里/小时”重复，A项赘余；B项“速度为600多公里”缺时间单位，表述不完整；D项“速度约为600公里”同样缺时间单位。C项“最高时速为600公里”简洁规范，且“最高”与“时速”搭配准确，故选C。' WHERE id=297933 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='首句应提出唯物主义的基本观点，①是对③中“外在世界客观存在”的进一步说明，故③①相连。④“但是”转折，引出唯心主义反驳，⑤承接④说明反驳内容，②以贝克莱为例具体论证，故顺序为③①④⑤②。A项⑤接③逻辑断裂，C、D以①开头缺乏总起，均不选。' WHERE id=297934 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297935 AND answer='C' AND disabled=0;
UPDATE questions SET explanation='A项中“不止”应改为“不只”。“不止”表示数量或范围超出，如“不止一次”；“不只”才是关联词，表递进，与“而是”搭配构成“不只……而是……”。B项“与其说……不如说”表选择，恰当；C项“宁可……也不要”表取舍，恰当；D项“之所以……是因为”表因果，恰当。故A项使用不恰当。' WHERE id=297937 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='语段列举了淮河上游贾湖遗址及中下游多个遗址出土人工栽培水稻的证据，时间跨度从距今8000多年前到5000年前，均属新石器时代中期及以后，说明淮河流域在新石器中期已有人工种植水稻。B项错误，材料只显示上游遗址时间略早，但未比较整个流域历史早晚；C项无中生有，未提及长江流域；D项绝对化，材料仅说明发现人工栽培稻，未否定野生稻存在。' WHERE id=297938 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='语段首句点明地缘从商业发展而来，随后以“而”转折强调地缘是契约社会的基础，后文全部围绕“契约”展开，解释其定义、条件与完成方式。血缘和身份只是作为对比参照，法律是契约的支撑要素，均非核心。关键词应同时涵盖论述主体“地缘”与核心概念“契约”，故选B。' WHERE id=297939 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='“一锤定音”本指凭一句话作出最后决定，含果断、权威的褒义。但文中描述人们用流行语简化复杂议题、压制思辨，明显是批评态度，属于褒词贬用。A项“褒词褒用”与文意相悖；C、D项均不符合该词本身褒义属性。' WHERE id=297940 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297941 AND answer='B' AND disabled=0;
UPDATE questions SET explanation='谣言表层是夸张形式，深层才反映实质社会焦虑。鸡有四只翅膀的荒谬说法，表层是吸引眼球，深层指向公众对食品安全的普遍担忧，即食物安全可能存在问题。A项是公众素养问题，属于表层归因；B、C项均属生物技术或基因变异，是谣言借用的形式，并非其传达的社会焦虑实质。' WHERE id=297942 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='文段通过对比“大刘记印”与“长沙王印”尺寸相近，且两印主人均为上层贵族，推断西汉私人用印规制应与之相同。“长沙王印”约合汉尺七分，故横线处应填“七分”。其余选项尺寸均与文中提及的“皇后之玺”“诸侯王玺”对应，不符合“私人用印”的推断依据。' WHERE id=297943 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297944 AND answer='B' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297945 AND answer='D' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297946 AND answer='C' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297947 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='C项将“周公教王遂过”误解为“周公比成王做得更错”，原文意为“周公引导成王犯过错”，而非比较周公与成王谁更错。A、B、D均准确对应原文句意，无偏差。考点在于“遂过”的“遂”应释为“促成、引导”，而非“更加”。' WHERE id=297948 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297949 AND answer='A' AND disabled=0;
UPDATE questions SET explanation='“辨”在此处意为辨明是非，而非辨伪或辩解。柳宗元借桐叶封弟的史事，批驳“天子无戏言”的绝对化观点，主张君主言行应合于道义，臣子应据理谏正，核心是阐发政治理念而非考证史实。A项误将“辨”作考证，且原文并非否定周公所为；C项“为成王辩解”与作者批判戏言的态度相悖；D项“隔空辩论”无文本依据。故选B。' WHERE id=297950 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='蚂蚁沿半圆弧缓慢爬行，可视为动态平衡。支持力方向始终垂直圆弧切线指向圆心，其大小等于重力沿半径方向的分量。从a到最高点，重力与半径夹角逐渐减小，支持力增大；从最高点到b，夹角增大，支持力减小，故支持力先增大后减小。摩擦力沿切线方向，与重力沿切线分量平衡，从a到最高点摩擦力减小，之后增大，并非不变或单向向下。A、B中摩擦力方向判断错误，D大小不变错误。故选C。' WHERE id=297953 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='反应前后总质量不变，可算出M=15+15+25+20-10-10-0=55，B错。甲、丙质量增加，乙、丁质量减少，说明反应物是乙和丁，生成物是甲和丙，属于化合反应而非分解，C对。丁是反应物，可能是单质也可能是化合物，A错。甲增加5g，丙增加25g，质量比为1:5，不是15:27，D错。' WHERE id=297954 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干由行星具有与地球相似的温度和气候条件，推出可能发现生命，隐含了生命存在只需相似温度气候这一前提。A项直接指出该行星的生命存在条件与地球类似，补全了从环境相似到生命可能的跳跃，是必要前提。B项距离远近与生命存在无关；C项观测时间属于操作层面，非前提；D项强调生物需固定温湿条件，但未说明该行星满足，且“固定”过于绝对，不如A项直接支撑结论。故A正确。' WHERE id=297957 AND answer='A' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='结论是若将服务贸易计入，贸易不平衡论就站不住，即逆差会缩小甚至消失。这需要假设美国对华服务贸易存在高额顺差，才能抵消部分货物逆差。A项若为逆差反而会加剧不平衡；C、D项只涉及购买行为，未明确顺差方向，无法支撑结论。' WHERE id=297958 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干建议多吃膳食纤维延缓大脑衰老，关键链条是膳食纤维→丁酸盐→减轻小胶质细胞促炎表型。B项直接建立丁酸盐与减轻炎症、增强抗炎能力的联系，补全了论证链条，支持力度最强。A项只提到产生短链脂肪酸，未明确丁酸盐及对大脑的作用；C项口腔运动与大脑功能无关；D项肠道蠕动与认知功能无直接关联，均属无关或间接项。' WHERE id=297959 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干断定“患上痛风”是判断“吃了太多肉类海鲜、畅饮啤酒”的必要条件，即“患痛风→吃多喝多”。削弱必要条件需举反例：吃多喝多但未患痛风，直接否定“患痛风是必不可少条件”。D项正是此反例。A项支持；B项说明痛风可由其他原因导致，但未否定题干中“患痛风者必吃多喝多”的必要条件关系；C项无关。故D项最能削弱。' WHERE id=297960 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干通过实验组病死率8.8%远低于对照组39%推出药物有效，但对照组样本仅18例，且两组重症率虽相近，却未提及两组患者年龄、基础疾病等关键变量是否均衡。B项指出同期整体病死率仅4.7%，远低于实验组的8.8%，说明该药组的病死率反而高于未用药的整体人群，直接削弱了“药物有效”的结论。A项成分未公开与疗效无关；C项患病率低不涉及病死率；D项古籍记载更不能证明现代疗效。故B项最能质疑。' WHERE id=297961 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='计划要求减少上网时间，但新学习计划的所有课后作业都需在线完成和提交，学生为完成作业不得不增加上网时间，导致减少上网时间的要求与学习计划本身冲突，成绩提升未达预期。A项主动减少更多上网时间反而可能提升成绩，无法解释；C项说明减少上网不影响新计划，排除；D项过去预测成功与本次无关。' WHERE id=297962 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='五真一假。赵、吴话真，钱话真，孙话真，周话真。孙不与赵李同队，排除A、D。C中钱孙吴，周不能与赵吴同队，只能配钱孙或李孙或钱李，但孙不与李同队、钱李不同队，且孙已与钱吴同队，周无法组队，排除。B中钱孙周，满足所有条件，故选B。' WHERE id=297964 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='题干仅知小陈4项、小李5项，小孔数量未知，故A、C无法推出；B需比较所有人，信息不足。因小李敬佩小孔，若小孔≤5项，则小李比小孔多；若小孔>5项，则小孔比小陈多。两种情况必有一种“有人比其敬佩的人多”，故D必然成立。' WHERE id=297965 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297966 AND answer='B' AND disabled=0;
UPDATE questions SET disabled=1 WHERE id=297967 AND answer='C' AND disabled=0;
UPDATE questions SET explanation='行政法律关系是行政主体在行使行政职权过程中与相对人形成的权利义务关系。C项中税务局宣传税法属于事实行为，不产生法律上的权利义务，故不形成行政法律关系。A项是内部行政关系，B项是行政处罚，D项是司法审查，均属行政法律关系范畴。' WHERE id=297977 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='行政监督的核心在于对决策权的制约，因为决策是行政管理的起点和基础，决策失误会导致后续执行偏离公正与高效。监督决策是否科学、合法，能从源头防止权力滥用，故其重要性超过对执行行为或自由裁量权的具体监督。干扰项中，A、B、D虽涉及监督内容，但均属执行层面的局部控制，而决策监督具有全局性和根本性，因此选C。' WHERE id=297982 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=297984 AND answer='D' AND disabled=0;
UPDATE questions SET explanation='火星昼夜温差虽大，但月球因无大气层，昼夜温差可达约300℃，远超火星（约100℃），故D项“火星昼夜温差比月球大”错误。火星有稀薄大气，探测器进入时需耐烧蚀隔热材料，B正确；火星与地球距离远，发射窗口约26个月一次，远少于月球每月多次，A正确；月球正面始终朝向地球，通信无遮挡，无需中继，C正确。' WHERE id=297985 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
