UPDATE questions SET disabled=1 WHERE id=299006 AND answer='B' AND disabled=0;
UPDATE questions SET explanation='信息焦虑的核心是“过量信息”与“难以获取、处理、利用所需信息”共同导致负面情绪。D项中，小李面对大量外文论文，因英语欠佳无法筛选所需信息，产生崩溃感，完全符合定义。A项只是沉迷信息，未体现难以处理；B项是骚扰信息过多，但并非主动获取所需信息困难；C项是游戏成瘾，与信息焦虑无关。' WHERE id=299009 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='气候移民的关键是“因气候或自然环境恶化”导致“无法在原居住地生存”而“大规模迁移”。D项中全球变暖导致海平面上升、岛屿被淹，居民被迫搬迁，完全符合因果链条。A项是为生态保护而主动搬迁，非生存所迫；B项是季节性避寒，非永久迁移；C项虽因干旱迁移，但“陆陆续续”体现非大规模同时迁移，且“寻找新居住地”未明确是否因无法生存，不如D项直接对应“被迫”。' WHERE id=299012 AND answer='D' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET explanation='口碑营销的关键是消费者在亲友间自发推荐，且企业运用手段促成。C项李阿姨因发布使用过程获点赞而换回保健枕，属于企业以奖励手段激励消费者在朋友圈（亲友圈）进行介绍推荐，符合定义。A项小张晒化妆品是个人行为，无企业手段介入；B项是广告宣传，非消费者间推荐；D项是传统促销，非亲友间介绍。故C正确。' WHERE id=299015 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
