UPDATE questions SET explanation='A、B、D均为被动句式：A“不能容于远近”用“于”表被动；B“为操所先”用“为……所”表被动；D“见笑于大方之家”用“见……于”表被动。C“得之心而寓之酒”是省略介词“于”的状语后置句，意为“在心里得到它，在酒中寄托它”，并非被动句，故与其他三项不同。' WHERE id=299104 AND answer='C' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
UPDATE questions SET disabled=1 WHERE id=299105 AND answer='C' AND disabled=0;
UPDATE questions SET explanation='B项先交代“越往古代追溯，亲历可能性越小”这一前提，自然引出“借助历史资料”的结论，再用“然而”转折指出资料可靠性降低，逻辑链条清晰。A项因果倒置，先讲借助资料再讲亲历可能性小，顺序别扭；C项转折后直接接结论，因果与转折关系混乱；D项“虽然…然而”搭配不当，且“因而”引导的结果放最后，因果顺序颠倒。' WHERE id=299107 AND answer='B' AND disabled=0 AND (explanation IS NULL OR TRIM(explanation)='');
